 "content": "from collections import deque


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 or (r, c) in seen:
                continue
            comp = {(r, c)}
            seen.add((r, c))
            q = deque([(r, c)])
            while q:
                y, x = q.popleft()
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 5 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        comp.add((ny, nx))
                        q.append((ny, nx))
            top = min(y for y, x in comp)
            bottom = max(y for y, x in comp)
            left = min(x for y, x in comp)
            right = max(x for y, x in comp)
            if top == bottom or left == right:
                continue
            # An open rectangular frame has a single missing cell in its top edge.
            gaps = [x for x in range(left + 1, right) if grid[top][x] != 5]
            if len(gaps) != 1:
                continue
            gap = gaps[0]
            if not (all(grid[y][left] == 5 and grid[y][right] == 5 for y in range(top, bottom + 1))
                    and all(grid[bottom][x] == 5 for x in range(left, right + 1))):
                continue
            # Paint the opening and enclosed area, then extend the opening leftward.
            for x in range(left + 1, right):
                out[top][x] = 2
            for y in range(top + 1, bottom):
                for x in range(left + 1, right):
                    out[y][x] = 2
            if top > 0:
                for x in range(gap + 1):
                    if out[top - 1][x] == 0:
                        out[top - 1][x] = 2
    return out
